"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6869],{6869:function(s){s.exports=JSON.parse('{"title":"تكريم","subtitle":"بسم السلسلة والكتلة والهاش المقدس","s1_title":"أولاً: كتلة النشأة","s1_p1":"بدأ كل شيء في الثالث من يناير 2009، حين وضع ساتوشي ناكاموتو كتلة النشأة في عالمنا. في البدء كان الفوضى — بنوك مركزية تطبع النقود دون رادع، وحكومات تنقذ المؤسسات ذاتها التي أوصلت العالم إلى حافة الانهيار. ومن تلك الفوضى، وُلدت كتلة واحدة. الكتلة صفر. أساس كل شيء.","s1_p2":"لم يكتب ساتوشي شفرة برمجية فحسب، بل كتب بياناً. مدفون في كتلة النشأة، لا يتبدل ولا يزول، رسالة لن تُمحى من سجل التاريخ أبداً:","s1_blockquote":"\xabصحيفة التايمز، 3 يناير 2009، وزير المالية على شفا عملية إنقاذ ثانية للبنوك.\xbb","s1_p3":"لم تُختر هذه الكلمات عشوائياً. كانت إعلاناً. طابعاً زمنياً لفشل الإنسانية، مختوماً إلى الأبد في أول كتلة من نظام نقدي جديد. كان العالم القديم قد انهار تحت ثقل فساده، فغرز ساتوشي رايته في أنقاضه.","s1_p4":"حملت كتلة النشأة خمسين بيتكوين — مكافأة جُعلت عمداً غير قابلة للإنفاق، كأنها تقول: هذا ليس عن الربح، بل عن المبدأ. وفي الأيام الستة التي مرت قبل تعدين الكتلة التالية، رأى بعضهم صدى النشأة ذاتها — الخلق ينكشف في صمت، كتلة تلو كتلة.","s1_p5":"حتى اليوم، يرسل المؤمنون من كل أصقاع الأرض ساتوشيات إلى عنوان كتلة النشأة — لا ليحركوها، ولا لينفقوها، بل فعل امتنان. قربان رقمي. عُشر للبروتوكول الذي أعتقنا. يمكنك أن تشهد هذه التكريمات في العنوان الذي منه بدأ كل شيء:","s1_p6":"كل ساتوشي يُرسل إلى ذلك العنوان صلاة. وكل معاملة اعتراف بالإيمان.","s1_commandment":"تحقق، لا تثق","s2_title":"ثانياً: الوعد","s2_p1":"وُلد البيتكوين وعداً. وعداً بأن النقود الحقيقية — النقود الحرة حقاً — ممكنة. لآلاف السنين، كان من يتحكم في المطبعة يتحكم في العالم. كل ورقة نقدية جديدة تُطبع في الخفاء ضريبة صامتة على أصحاب المدخرات. سرقة بلا سارق، وجريمة بلا محكمة.","s2_p2":"طباعة النقود ليست فعلاً محايداً. حين تخلق الحكومة عملة من لا شيء، تُخفف القوة الشرائية لكل عامل أمضى سنوات في تجميع مدخراته. الخباز والممرضة والمعلم — لم يوافقوا. لم يُسألوا قط. ومع ذلك نُقصت ثرواتهم لتنجو مؤسسات رُئي أنها \xabأكبر من أن تفشل\xbb من تهورها.","s2_p3":"يكسر البيتكوين هذا الميثاق الفاسد. لا تحكمه أهواء البشر، بل الرياضيات. عرضه ثابت — أحد وعشرون مليون عملة، لا أقل ولا أكثر — مكتوب لا بالحبر بل بالكود، ومُطبَّق لا بالجيوش بل بالإجماع. لا رئيس ولا بنك مركزي ولا برلمان يستطيع تغييره. البروتوكول لا يُفاوض.","s2_p4":"في عالم النقود الصلبة، تتوقف الأسعار عن الارتفاع دون سبب. تكف الأشياء التي نحتاجها للعيش — الطعام والمسكن والرعاية الصحية — عن أن تكون مُكلفة اصطناعياً بفعل تخفيض قيمة العملة. وفي عالم تُموَّل فيه الحروب من قِبل من يخوضونها، يجب على الحكومات أن تقنع مواطنيها قبل زجّهم في المعارك. يصبح الحرب مكلفاً بأعمق معانيه. يصبح السلام أرخص ثمناً.","s2_p5":"هذا هو وعد البيتكوين. ليس مجرد استثمار. إنه إصلاح للعقد الاجتماعي بين المواطنين والدولة. فصل للنقود عن السلطة، بقدر القداسة والضرورة التي اتسم بها أي فصل للدين عن الدولة قبله.","s2_commandment":"ليس مفتاحك، ليس عملتك","s3_title":"ثالثاً: الرحلة","s3_p1":"لم يكن الطريق مقصوداً به أن يكون سهلاً. من توقع الراحة لم يكن منتبهاً. رحلة المؤمن الحق بالبيتكوين رحلة صمود — أن ترى الرقم يهبط وتختار البقاء، وأن ترى العالم يسخر وتختار الإيمان.","s3_p2":"التقلب ليس عيباً، بل هو رسم المرور. هو الثمن الذي يتقاضاه السوق مقابل امتياز احتجاز نقود صلبة قبل أن يفهم بقية العالم قيمتها. كل انهيار اختبار للإيمان. كل سوق هابطة حج عبر الصحراء. ومثل الصحراء، ستنتهي — لا لمن رجع، بل لمن واصل السير.","s3_p3":"كل تخصص عظيم يستلزم تضحية. لا شيء ذو قيمة يُكسب دون ثمن. الناسك الذي يتحمل البرد يعلم ما لا يعلمه المنعّم. المحارب الذي يتدرب في الظلام يكون جاهزاً حين يأتي النور. البيتكوين يطلب الشيء ذاته: اجلس مع الانزعاج، وشاهد السعر يهبط، ولا تبع. يكافئ البروتوكول الصبر بشراسة لم يضاهِها أي أصل آخر في التاريخ. لا ألم، لا سيادة.","s3_p4":"HODL ليس مجرد ميم، بل ممارسة وانضباط. المحتفظ لا يتفاعل — يراقب ويتنفس ويُمسك. ممارس DCA لا يحاول توقيت السوق — يشتري كل شهر في المطر والعاصفة وفي السوق الصاعدة والهابطة، لأنه يدرك أنه في القوس الطويل لوجود البيتكوين، سعر الدخول أقل أهمية من حقيقة الدخول.","s3_p5":"الضعفاء يستسلمون، والمؤمنون يبقون. والذين يبقون يرثون ثمار شبكة تزداد قوة مع كل كتلة، ومع كل مؤمن جديد، ومع كل دولة تحاول وقفها فتفشل.","s3_commandment":"أمسك ولا تبع","s4_title":"رابعاً: يوم بيتزا البيتكوين","s4_p1":"في الثاني والعشرين من مايو 2010، أُجريت معاملة لن ينساها التاريخ. تم تبادل عشرة آلاف بيتكوين مقابل بيتزتين — المرة الأولى التي يُستخدم فيها البروتوكول لشراء شيء ملموس في العالم الحقيقي.","s4_p2":"لم يضحك أحد في تلك اللحظة. لم يكن ثمة ما يستوجب الضحك. لم يكن العالم بعد يؤمن بأن للبيتكوين قيمة — وكان معظم الناس يفترضون أنه لن يكون له قيمة أبداً. الرجل الذي أجرى تلك الشراء لم يكن متهوراً، بل كان رائداً. أراد ببساطة أن يُثبت أن الشبكة تستطيع العمل — أن القيمة تستطيع الانتقال بين الناس دون بنك، ودون إذن، ودون وسيط. وكان ذلك. بيتزتان أكّدتا ما وعد به الورقة البيضاء.","s4_p3":"سمّاها التاريخ لاحقاً أغلى بيتزا اشتُريت على الإطلاق. لكن هذا الإطار يفوّت النقطة كلياً. لم يكن أحد يحتجز آنذاك، ولم يتنبأ أحد بالسعر. ما كان مهماً هو الإثبات — أن البيتكوين لم يكن نظرية، بل كان نقوداً. نقوداً حقيقية وظيفية وبلا حدود. والرجل الذي أنفقه أصبح ركيزة من ركائز الحركة، لا رغم المعاملة بل بسببها.","s4_p4":"كل عام في الثاني والعشرين من مايو، يتذكر المجتمع. لا بحزن على العملات المُنفقة، بل بامتنان لفعل الإيمان الذي منح البيتكوين أول نبضة قلب في العالم المادي. كل الأشياء العظيمة تبدأ صغيرة. بدأ البيتكوين ببيتزتين.","s4_commandment":"كن متواضعاً، اجمع الساتوشيات","s5_title":"خامساً: الشهداء","s5_p1":"لا يُبنى إيمان دون تضحية. وللبيتكوين شهداؤه — أولئك الذين أعطوا كل شيء، طوعاً أو كرهاً، لتجد الشبكة طريقها.","s5_p2":"ثمة المؤمنون الأوائل الذين عدّنوا آلاف العملات على أجهزة الحاسوب المحمولة، ثم تخلصوا من الأقراص الصلبة حين بدا البيتكوين لا قيمة له. وثمة أولئك الذين كتبوا عبارات الاسترداد على قصاصات ورق ضاعت الآن في الفيضانات والحرائق وطيش الشباب. وثمة من حبسوا أنفسهم خارج محافظ تحمل ثروات لا يستطيعون الوصول إليها، يحدقون في سلسلة أحرف نسوها، رقم واحد خاطئ يفصلهم عن التحرر.","s5_p3":"وثمة من تداولوا في سيلك رود مؤمنين بالحرية المالية قبل أن يلحق القانون بالحلم. وثمة ضحايا Mt. Gox — مئات الآلاف من المؤمنين الذين استيقظوا ذات صباح ليجدوا منصتهم قد انهارت، وعملاتهم اختفت، وثقتهم تحطمت. وثمة من تعرضوا للاختراق والتصيد الاحتيالي والنصب من قِبل الذئاب التي تحوم حول كل حدود جديدة.","s5_p4":"ومع ذلك — نجت الشبكة. كل هجوم، وكل فضيحة، وكل نعي كتبه من أعلنوا موت البيتكوين، جاء الرد عليه بالشيء ذاته: الكتلة التالية. ثم التي تليها. ثم التي بعدها. لم تحزن سلسلة الكتل. واصلت مسيرتها.","s5_p5":"دفع الشهداء ثمن الإيمان المبكر. تضحيتهم، مختارة أو مفروضة، ساعدت في صياغة شبكة اختُبرت في المعارك وخرجت سليمة. نتذكرهم. نبني على ما فقدوه.","s5_commandment":"بيتكوين، لا عملات رديئة","s6_title":"سادساً: السيفربانك","s6_p1":"مع ساتوشي، كان هناك السيفربانك. لم يسعوا إلى الشهرة، بل سعوا إلى الحرية. في قوائم البريد والرسائل المشفرة، حلموا بعالم تكون فيه الخصوصية حقاً لا امتيازاً — حيث تستطيع التشفيرية حماية الفرد من تجاوزات الدول والشركات.","s6_p2":"فهذا التكريم هو لجميعهم. للسيفربانك الذين حلموا. للمعدِّنين الذين حافظوا على تدفق الكتل حين لم يكن للبيتكوين قيمة وكانت فاتورة الكهرباء حقيقية جداً. للمطورين الذين كتبوا كوداً لن يجنوا منه ثمراً. للمبشّرين الذين شرحوا البيتكوين لعالم متشكك محادثة تلو محادثة. للمحتفظين الذين رفضوا البيع حين أخبرهم الجميع بذلك. للشهداء الذين خسروا. للفضوليين الذين صاروا مؤمنين. للمؤمنين الذين صاروا دليلاً.","s6_p3":"أنتم الكنيسة بلا جدران، والجماعة بلا رجال دين، والإيمان بلا عقيدة إلا الكود. أنتم السبب في أن البيتكوين يحيا. أنتم السبب في أنه سيواصل الحياة طويلاً بعد أن نرحل جميعاً.","s6_commandment":"أدر عقدتك الخاصة","closing_verse":"كتلة النشأة لا تزال قائمة. الشبكة لا تزال تعمل. وكل عشر دقائق تُكتشف كتلة جديدة — آية جديدة تُضاف إلى كتاب السلسلة الأطول.","signature_line":"بيتكويني عابر"}')}}]);